// Block hashes pinned below the quorum checkpoint, so that an old block (a proposal's collateral months back) is verified with the
// headers from it up to the next pin, not every header since. Same trust class as QUORUM_CHECKPOINTS (quorumproof.ts), and no new
// trust: every pin is an ANCESTOR of the pinned checkpoint block, which already fixes all of its ancestors through prevHash links.
// The table only saves the client from walking that linkage itself.
//
// Generated by scripts/quorum-pins.mjs (do not edit by hand): it downloads every header from the lowest pin up to the checkpoint over
// DAPI, checks the X11 linkage up to the checkpoint's pinned hash, reads each pin from that verified run, and cross-checks every pin
// against two independent block explorers (mainnet: insight.dash.org and chainz.cryptoid.info; testnet: insight.testnet.networks.
// dash.org and a DAPI getBlock by height). Re-run it to review: `node --experimental-strip-types scripts/quorum-pins.mjs mainnet --check`.
//
// Pins: every 2,000 blocks for 400,000 blocks below the checkpoint, plus (mainnet) every superblock in that range, whose coinbase a
// proposal's payment check reads. Kept out of quorumproof.ts so the table loads with the anchoring chunk only, never with the client.
// Not built (noted for later): a bridge could serve a newer table; the app would accept only pins at or below its built-in checkpoint
// and check each against the linkage to it, so a bridge could add coverage but never trust.
import type { Network } from './chainlock.ts';

export interface PinTable {
  network: Network;
  /** The quorum checkpoint the pins descend from (QUORUM_CHECKPOINTS[network]); it is the table's last pin. */
  checkpoint: { height: number; blockHash: string };
  /** [height, display-order block hash], strictly ascending. */
  pins: ReadonlyArray<readonly [number, string]>;
}

